module accu
    (
      input clk,
      input rst_n,
      input [7:0] data_in,
      input valid_in,
      output reg valid_out,
      output reg [9:0] data_out
    );

    reg [1:0] count;
    reg [9:0] total;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            count <= 0;
            valid_out <= 0;
            data_out <= 0;
            total <= 0;
        end
        else if(valid_in) begin
            if(count < 4) begin
                total <= total + data_in;
                count <= count + 1;
            end
            else begin
                valid_out <= 1;
                total <= total + data_in;
                count <= count + 1;
            end
        end
        else begin
            count <= 0;
            valid_out <= 0;
        end
    end

    assign data_out = total;
endmodule
